function c(e){switch(String(e||"").trim().toLowerCase()){case"completed":case"success":case"succeeded":return"completed";case"pending":case"pending_manual":return"pending";case"processing":return"processing";case"failed":case"rejected":case"declined":case"refunded":case"error":return"failed";case"cancelled":case"canceled":return"cancelled";default:return"unknown"}}function a(e){return c(e)==="completed"}function s(e){const n=c(e);return n==="pending"||n==="processing"}export{s as a,c as g,a as i};
